import { _decorator, assetManager, AssetManager, Component, ImageAsset, sys, view } from 'cc';
import { PREVIEW } from 'cc/env';
import GameConfigManager from '../config/GameConfigManager';

const { ccclass } = _decorator;

// 黑邊背景圖 放在遊戲包裡
const BACKDROP_MAIN_PATH = 'resources/Images/backdrop_main';
const BACKDROP_FREE_PATH = 'resources/Images/backdrop_free';

/**
 * 是否固定比例 entry 或殼頁會設旗標 預覽沒有旗標 跨網域的殼頁也寫不進來 桌面瀏覽器直接視為固定比例
 */
export function isFixedRatio(): boolean {
    if (!sys.isBrowser) return false;
    if ((globalThis as Record<string, unknown>).__subGameFixedRatio__ === true) return true;
    return PREVIEW && !sys.isMobile;
}

/** 固定比例時在畫布上面蓋住設計框外的黑邊 黑邊鋪背景圖 不是固定比例就什麼都不做 */
@ccclass('1001/FixedRatioFrame')
export class FixedRatioFrame extends Component {
    private static instance: FixedRatioFrame | null = null;

    private bars: HTMLDivElement[] = [];
    private backdropUrls: { main: string; free: string } | null = null;
    private backdropFree = false;

    /**
     * 切換一般或免費遊戲的黑邊背景圖
     *
     * @param free 是否為免費遊戲
     */
    public static setFree(free: boolean): void {
        const frame = FixedRatioFrame.instance;
        if (!frame) return;
        frame.backdropFree = free;
        frame.applyBackdrop();
    }

    protected override onLoad(): void {
        FixedRatioFrame.instance = this;
        view.on('design-resolution-changed', this.layout, this);
        window.addEventListener('resize', this.layout);
        this.layout();
    }

    protected override start(): void {
        void this.loadBackdrop();
    }

    protected override onDestroy(): void {
        view.off('design-resolution-changed', this.layout, this);
        window.removeEventListener('resize', this.layout);
        for (const bar of this.bars) bar.remove();
        this.bars = [];
        if (FixedRatioFrame.instance === this) FixedRatioFrame.instance = null;
    }

    private readonly layout = (): void => {
        if (!isFixedRatio()) {
            for (const bar of this.bars) bar.style.display = 'none';
            return;
        }
        this.ensureBars();
        const design = view.getDesignResolutionSize();
        const winW = window.innerWidth;
        const winH = window.innerHeight;
        const designAspect = design.width / design.height;
        // 設計框置中 框外的兩條就是黑邊
        let frameW = winW;
        let frameH = winH;
        if (winW / winH > designAspect) frameW = winH * designAspect;
        else frameH = winW / designAspect;
        const gapX = (winW - frameW) / 2;
        const gapY = (winH - frameH) / 2;
        const [first, second] = this.bars;
        if (gapX >= 1) {
            this.place(first, 0, 0, gapX, winH);
            this.place(second, winW - gapX, 0, gapX, winH);
        } else if (gapY >= 1) {
            this.place(first, 0, 0, winW, gapY);
            this.place(second, 0, winH - gapY, winW, gapY);
        } else {
            first.style.display = 'none';
            second.style.display = 'none';
        }
    };

    private place(el: HTMLDivElement, x: number, y: number, w: number, h: number): void {
        el.style.display = 'block';
        el.style.left = `${x}px`;
        el.style.top = `${y}px`;
        el.style.width = `${w}px`;
        el.style.height = `${h}px`;
    }

    private ensureBars(): void {
        if (this.bars.length) return;
        for (let i = 0; i < 2; i++) {
            const el = document.createElement('div');
            // 蓋在畫布上面 不擋操作 沒有圖時就是純黑
            el.style.cssText =
                'position:fixed;display:none;z-index:2147483000;pointer-events:none;background-color:#000;background-attachment:fixed;background-size:cover;background-position:center;background-repeat:no-repeat';
            document.body.appendChild(el);
            this.bars.push(el);
        }
        this.applyBackdrop();
    }

    private async loadBackdrop(): Promise<void> {
        if (!isFixedRatio()) return;
        const bundle = await this.waitBundle();
        const paths = [BACKDROP_MAIN_PATH, BACKDROP_FREE_PATH];
        if (!bundle || !paths.every((path) => bundle.getInfoWithPath(path, ImageAsset))) {
            console.warn('[FixedRatioFrame] 沒有黑邊背景圖 黑邊維持純黑');
            return;
        }
        try {
            const [main, free] = await Promise.all(
                paths.map(
                    (path) =>
                        new Promise<string>((resolve, reject) => {
                            bundle.load(path, ImageAsset, (error, asset) => (error ? reject(error) : resolve(asset.nativeUrl)));
                        })
                )
            );
            if (!this.isValid) return;
            this.backdropUrls = { main, free };
            this.applyBackdrop();
        } catch (error) {
            console.warn('[FixedRatioFrame] 讀取黑邊背景圖失敗 黑邊維持純黑', error);
        }
    }

    // bundle 在 GameRoot 初始化時才載入 這裡等它出現 最多等一分鐘
    private async waitBundle(): Promise<AssetManager.Bundle | null> {
        for (let i = 0; i < 600; i++) {
            const bundle = assetManager.getBundle(GameConfigManager.GAMEID);
            if (bundle) return bundle;
            await new Promise<void>((resolve) => setTimeout(resolve, 100));
            if (!this.isValid) return null;
        }
        return null;
    }

    private applyBackdrop(): void {
        const urls = this.backdropUrls;
        if (!urls || !this.bars.length) return;
        const image = `url("${(this.backdropFree ? urls.free : urls.main).replace(/"/g, '%22')}")`;
        for (const bar of this.bars) bar.style.backgroundImage = image;
        // 另一張先載進快取 切換時不會閃
        new Image().src = this.backdropFree ? urls.main : urls.free;
    }
}
