import type { SlotApiHistoryList, SlotApiHistoryRound, SlotApiHistoryRoundDetail } from './SlotApiTypes';
import type { BetHistoryDetail, BetHistoryPage, BetHistorySummary } from '../models/BetHistory';
import type { SlotRoundMapper } from './SlotRoundMapper';
import { subtractDecimal } from './SlotResponseAdapter';

/** `GET /player/history` 的列表與單局回應轉成 BetHistoryPage／BetHistoryDetail 的唯一轉換點 */
export class SlotHistoryMapper {
    /**
     * @param roundMapper 解析細單盤面用的轉換器（跟 spin 共用同一套盤面設定）。
     * @param amountScale 幣別小數位，算損益時至少保留這麼多位。
     */
    constructor(
        private readonly roundMapper: SlotRoundMapper,
        private readonly amountScale: number
    ) {}

    /**
     * 把注單列表轉成前端的分頁結構。
     *
     * @param list 列表模式的回應。
     * @returns 分頁結構；還有下一頁時 `nextCursor` 是下一頁的頁碼。
     */
    toBetHistoryPage(list: SlotApiHistoryList): BetHistoryPage {
        const hasMore = list.page < list.total_pages;
        return {
            items: (list.rounds ?? []).map((round) => this.toBetHistorySummary(round)),
            hasMore,
            nextCursor: hasMore ? String(list.page + 1) : undefined,
        };
    }

    /**
     * 把單局重播轉成前端結構。
     *
     * 細單 `result` 裡的倍數是底注倍數，換成金額用母單的 `base_bet_amount`（購買局的 `bet_amount` 是購買價、不是底注）。
     *
     * @param detail 單局模式的回應。
     * @returns 明細結構。
     */
    toBetHistoryDetail(detail: SlotApiHistoryRoundDetail): BetHistoryDetail {
        const summary = this.toBetHistorySummary(detail.round);
        return {
            engineWin: summary.engineWin,
            rawEngineWin: summary.rawEngineWin,
            summary,
            ...this.roundMapper.toRoundSteps(detail.details ?? [], detail.round.base_bet_amount),
        };
    }

    /**
     * 把母單轉成前端的摘要欄位。
     *
     * 新列表沒有結算後餘額，`balanceAfter` 留空字串。
     *
     * @param round 母單。
     * @returns 摘要結構。
     */
    private toBetHistorySummary(round: SlotApiHistoryRound): BetHistorySummary {
        return {
            operationId: round.round_id,
            gameCode: round.game_id,
            currency: round.currency,
            betAmount: round.bet_amount,
            winAmount: round.payout_amount,
            rawEngineWin: round.payout_amount,
            engineWin: round.payout_amount,
            profit: subtractDecimal(round.payout_amount, round.bet_amount, this.amountScale),
            balanceAfter: '',
            createdAtMs: round.settled_at_unix * 1000,
            buyFeature: round.spin_type === 'BUY_FEATURE',
            isFreeRound: (round.feature_flags ?? []).includes('FREE_GAME'),
        };
    }
}
